package com.grocery.controller; import com.grocery.entity.*; import com.grocery.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/customers") public class CustomerController{ private final CustomerRepository r; public CustomerController(CustomerRepository r){this.r=r;} @GetMapping public List<Customer> all(){return r.findAll();} @GetMapping("/{id}") public Customer one(@PathVariable Long id){return r.findById(id).orElseThrow();} @PostMapping public Customer save(@RequestBody Customer c){return r.save(c);} @PutMapping("/{id}") public Customer update(@PathVariable Long id,@RequestBody Customer c){c.setId(id); return r.save(c);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){r.deleteById(id);} }